package cn.musicsquare.app;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.concurrent.atomic.AtomicInteger;

public class NeteaseResolverTest {
    private JSONObject track()throws Exception{return MusicApi.base("netease","108485","Always Online","林俊杰").put("durationMs",225013).put("trial",true).put("trialDetectedByDuration",true);}
    private JSONObject payload()throws Exception{return new JSONObject().put("success",true).put("id","108485").put("song",new JSONObject().put("id",108485).put("duration_ms",225013)).put("levels",new JSONArray().put(level("lossless","https://m8.music.126.net/a.flac")).put(level("standard","http://m8.music.126.net/a.mp3")).put(level("exhigh","https://m8.music.126.net/b.mp3")));}
    private JSONObject level(String name,String url)throws Exception{return new JSONObject().put("level",name).put("url",url);}
    private void reject(JSONObject p)throws Exception{try{NeteaseResolver.parse(track(),p.toString());fail("reject invalid response");}catch(java.io.IOException expected){}}
    @Test public void retainsIdentityAndPrefersStandard()throws Exception{JSONObject r=NeteaseResolver.parse(track(),payload().toString());assertEquals("netease-108485",r.getString("uid"));assertEquals("netease",r.getString("source"));assertEquals("林俊杰",r.getString("artist"));assertEquals(3,r.getJSONArray("audioCandidates").length());assertTrue(r.getString("audioUrl").endsWith("a.mp3"));assertFalse(r.getBoolean("trial"));assertFalse(r.has("trialDetectedByDuration"));assertTrue(r.getString("lrcUrl").contains("id=108485"));}
    @Test public void rejectsEitherMismatchedId()throws Exception{JSONObject p=payload();p.put("id","999");reject(p);p=payload();p.getJSONObject("song").put("id",999);reject(p);}
    @Test public void rejectsWrongDuration()throws Exception{JSONObject p=payload();p.getJSONObject("song").put("duration_ms",30000);reject(p);}
    @Test public void rejectsExplicitPreview()throws Exception{reject(payload().put("freeTrialInfo",new JSONObject()));JSONObject p=payload();for(int i=0;i<p.getJSONArray("levels").length();i++)p.getJSONArray("levels").getJSONObject(i).put("trial",true);reject(p);}
    @Test public void rejectsNonCdnAndEmptyUrls()throws Exception{JSONObject p=payload().put("levels",new JSONArray().put(level("standard","https://music.126.net.evil.example/x.mp3")).put(level("exhigh","file:///tmp/x")));reject(p);reject(payload().put("levels",new JSONArray()));}
    @Test public void rejectsFailedResponseAndDeduplicates()throws Exception{reject(payload().put("success",false));JSONObject p=payload();p.getJSONArray("levels").put(level("standard","http://m8.music.126.net/a.mp3"));assertEquals(3,NeteaseResolver.parse(track(),p.toString()).getJSONArray("audioCandidates").length());}
    private String official(boolean trial,long time)throws Exception{return new JSONObject().put("data",new JSONArray().put(new JSONObject().put("id",108485).put("url","https://m8.music.126.net/original.mp3").put("time",time).put("freeTrialInfo",trial?new JSONObject():JSONObject.NULL))).toString();}
    @Test public void officialFullSkipsThirdParty()throws Exception{AtomicInteger calls=new AtomicInteger();JSONObject r=new NeteaseResolver(u->{assertTrue(u.startsWith("https://music.163.com/"));calls.incrementAndGet();return official(false,225013);}).resolve(track());assertEquals(1,calls.get());assertEquals("netease-public",r.getString("playbackProvider"));assertFalse(r.getBoolean("trial"));}
    @Test public void officialPreviewUsesThirdParty()throws Exception{for(boolean flag:new boolean[]{true,false}){AtomicInteger calls=new AtomicInteger();JSONObject r=new NeteaseResolver(u->{if(calls.getAndIncrement()==0){assertTrue(u.startsWith("https://music.163.com/"));return official(flag,30000);}assertTrue(u.startsWith("https://wzapi.com/"));return payload().toString();}).resolve(track());assertEquals(2,calls.get());assertEquals("wzapi",r.getString("playbackProvider"));assertFalse(r.getBoolean("trial"));}}
    @Test public void originalErrorOrEmptyUsesThirdParty()throws Exception{for(boolean network:new boolean[]{true,false}){AtomicInteger calls=new AtomicInteger();JSONObject r=new NeteaseResolver(u->{if(calls.getAndIncrement()==0){if(network)throw new java.io.IOException("offline");return "{\"data\":[{\"id\":108485,\"url\":null}]}";}return payload().toString();}).resolve(track());assertEquals(2,calls.get());assertEquals("wzapi",r.getString("playbackProvider"));}}
    @Test public void keepsHonestPreviewWhenThirdPartyFails()throws Exception{AtomicInteger calls=new AtomicInteger();JSONObject r=new NeteaseResolver(u->{if(calls.getAndIncrement()==0)return official(true,30000);throw new java.io.IOException("offline");}).resolve(track());assertTrue(r.getBoolean("trial"));assertTrue(r.getBoolean("neteaseFallbackAttempted"));assertEquals(2,calls.get());}
    @Test public void genuineShortSongDoesNotTriggerThirdParty()throws Exception{AtomicInteger calls=new AtomicInteger();JSONObject r=new NeteaseResolver(u->{calls.incrementAndGet();return official(false,30000);}).resolve(track().put("durationMs",30000));assertFalse(r.getBoolean("trial"));assertEquals(1,calls.get());}
    @Test public void bothFailuresAndBadIdsFailClearly()throws Exception{try{new NeteaseResolver(u->{throw new java.io.IOException("offline");}).resolve(track());fail();}catch(java.io.IOException e){assertTrue(e.getMessage().contains("均未"));}AtomicInteger calls=new AtomicInteger();try{new NeteaseResolver(u->{calls.incrementAndGet();return "{}";}).resolve(track().put("songid","bad&id=1"));fail();}catch(java.io.IOException e){assertEquals(0,calls.get());}}
    @Test public void officialFallbackClearsStaleCandidatesAndPreviewDetection()throws Exception{JSONObject t=track().put("audioCandidates",new JSONArray().put("https://m8.music.126.net/expired.mp3"));JSONObject r=MusicApi.parseNeteasePlayback(t,"{\"data\":[{\"id\":108485,\"url\":\"https://m8.music.126.net/full.mp3\"}]}");assertFalse(r.has("audioCandidates"));assertFalse(r.has("trialDetectedByDuration"));assertFalse(r.getBoolean("trial"));}
    @Test public void fillsMissingDurationWithoutOverwritingSearchDuration()throws Exception{JSONObject t=track();t.remove("durationMs");assertEquals(225013,NeteaseResolver.parse(t,payload().toString()).getLong("durationMs"));JSONObject p=payload();p.getJSONObject("song").put("duration_ms",225000);assertEquals(225013,NeteaseResolver.parse(track(),p.toString()).getLong("durationMs"));}
}
